<template>
  <div class="config-view"><el-card class="config-card"><template #header><div class="card-header"><span>系统配置管理</span><el-button type="primary" @click="saveConfigs" :loading="saving">保存配置</el-button></div></template><el-tabs v-model="activeTab">
    <el-tab-pane label="LLM 配置" name="llm"><el-form label-width="120px"><el-form-item label="Base URL"><el-input v-model="llmConfig.base_url" /></el-form-item><el-form-item label="API Key"><el-input v-model="llmConfig.api_key" type="password" show-password /></el-form-item><el-form-item label="模型名称"><el-input v-model="llmConfig.model" /></el-form-item><el-form-item label="温度"><el-slider v-model="llmConfig.temperature" :min="0" :max="2" :step="0.1" show-input /></el-form-item><el-form-item><el-button @click="testConnection('llm')">测试连接</el-button></el-form-item></el-form></el-tab-pane>
    <el-tab-pane label="Embedding 配置" name="embedding"><el-form label-width="120px"><el-form-item label="Base URL"><el-input v-model="embeddingConfig.base_url" /></el-form-item><el-form-item label="API Key"><el-input v-model="embeddingConfig.api_key" type="password" show-password /></el-form-item><el-form-item label="模型名称"><el-input v-model="embeddingConfig.model" /></el-form-item><el-form-item label="向量维度"><el-input-number v-model="embeddingConfig.dimension" :min="1" :max="4096" /></el-form-item><el-form-item label="最大输入 Token"><el-input-number v-model="embeddingConfig.max_tokens" :min="1" :max="1000000" /><span class="hint">请按当前 Embedding 模型文档配置，模型 API 通常不会返回该限制。</span></el-form-item><el-form-item><el-button @click="testConnection('embedding')">测试连接</el-button></el-form-item></el-form></el-tab-pane>
    <el-tab-pane label="Milvus 配置" name="milvus"><el-form label-width="120px"><el-form-item label="URI"><el-input v-model="milvusConfig.uri" /></el-form-item><el-form-item label="用户名"><el-input v-model="milvusConfig.user" /></el-form-item><el-form-item label="密码"><el-input v-model="milvusConfig.password" type="password" show-password /></el-form-item><el-form-item label="数据库名"><el-input v-model="milvusConfig.database" /></el-form-item><el-form-item><el-button @click="testConnection('milvus')">测试连接</el-button><el-button @click="loadRemoteCollections">刷新集合</el-button></el-form-item></el-form><div class="section-header"><h3>数据库集合 ({{ remoteCollections.length }})</h3><el-button type="primary" @click="showAddDialog=true">添加集合</el-button></div><el-table :data="remoteCollections" border><el-table-column prop="name" label="集合名称"/><el-table-column prop="description" label="描述" min-width="220" show-overflow-tooltip/><el-table-column prop="row_count" label="数据量"/><el-table-column label="操作" width="210" align="center"><template #default="{row}"><div class="collection-actions"><el-button @click="viewCollectionSchema(row)">查看</el-button><el-button @click="editCollection(row)">编辑</el-button><el-button type="danger" @click="deleteCollection(row.name)">删除</el-button></div></template></el-table-column></el-table></el-tab-pane>
    <el-tab-pane label="Agent 配置" name="agent"><el-form label-width="120px"><el-form-item label="最大迭代次数"><el-input-number v-model="agentConfig.max_iterations" :min="1" :max="50" /></el-form-item></el-form></el-tab-pane>
    <el-tab-pane label="MCP Server" name="mcp"><p class="schema-note">内置知识库 MCP Server 使用 stdio 启动。此处配置额外的远程 Streamable HTTP Server；仅管理员可见和修改。</p><div v-for="(server, index) in mcpServers" :key="server.id" class="mcp-server"><el-form label-width="120px"><el-form-item label="名称"><el-input v-model="server.name" /></el-form-item><el-form-item label="Server ID"><el-input v-model="server.id" :disabled="server._existing" /></el-form-item><el-form-item label="Streamable HTTP URL"><el-input v-model="server.url" placeholder="https://example.com/mcp" /></el-form-item><el-form-item label="Bearer Token"><el-input v-model="server.token" type="password" show-password placeholder="留空表示无需认证" /></el-form-item><el-form-item label="启用"><el-switch v-model="server.enabled" /></el-form-item><el-form-item><el-button @click="testMcpServer(server)">测试连接</el-button><el-button type="danger" @click="mcpServers.splice(index, 1)">移除</el-button></el-form-item></el-form></div><el-button @click="addMcpServer">添加远程 MCP Server</el-button></el-tab-pane>
  </el-tabs></el-card><el-dialog v-model="showAddDialog" title="创建 Milvus 集合" width="1450px"><el-form label-width="110px"><el-form-item label="集合名称"><el-input v-model="collectionForm.name" /></el-form-item><el-form-item label="集合描述"><el-input v-model="collectionForm.description" type="textarea" /></el-form-item></el-form><div class="field-header"><h3>字段 Schema</h3><el-button @click="addField">添加字段</el-button></div><el-table :data="collectionForm.fields" border><el-table-column label="字段名" min-width="120"><template #default="{row}"><el-input v-model="row.name" /></template></el-table-column><el-table-column label="类型" min-width="150"><template #default="{row}"><el-select v-model="row.data_type" @change="typeChanged(row)"><el-option v-for="type in fieldTypes" :key="type" :label="type" :value="type" /></el-select></template></el-table-column><el-table-column label="描述" min-width="150"><template #default="{row}"><el-input v-model="row.description" /></template></el-table-column><el-table-column label="主键" width="75"><template #default="{row}"><el-checkbox v-model="row.is_primary" @change="primaryChanged(row)" /></template></el-table-column><el-table-column label="自动生成" width="90"><template #default="{row}"><el-checkbox v-model="row.auto_id" :disabled="!row.is_primary" /></template></el-table-column><el-table-column label="最大长度/维度" min-width="180"><template #default="{row}"><el-input-number v-if="row.data_type === 'VARCHAR'" v-model="row.max_length" :min="1" :max="65535" /><el-input-number v-else-if="isVector(row.data_type)" v-model="row.dimension" :min="1" :max="32768" /><span v-else>-</span></template></el-table-column><el-table-column label="字段索引" min-width="190"><template #default="{row}"><el-select v-model="row.index_type" size="small" placeholder="选择索引"><el-option v-for="type in (isVector(row.data_type) ? ['AUTOINDEX','IVF_FLAT','IVF_SQ8','HNSW','FLAT'] : ['AUTOINDEX','INVERTED','STL_SORT','TRIE','BITMAP'])" :key="type" :label="type" :value="type" /></el-select><el-select v-if="isVector(row.data_type)" v-model="row.metric_type" size="small" style="margin-top:4px"><el-option v-for="metric in (row.data_type === 'BINARY_VECTOR' ? ['HAMMING','JACCARD'] : ['COSINE','L2','IP'])" :key="metric" :label="metric" :value="metric" /></el-select><div v-if="row.data_type==='FLOAT_VECTOR'&&row.index_type.startsWith('IVF_')" class="index-param"><span>nlist（聚类桶数，1–65536）</span><el-input-number v-model="row.index_params.nlist" :min="1" :max="65536" size="small" /></div><div v-if="row.data_type==='FLOAT_VECTOR'&&row.index_type==='HNSW'" class="index-param"><span>M（每个节点的邻居数）</span><el-input-number v-model="row.index_params.M" :min="2" :max="2048" size="small" /></div><div v-if="row.data_type==='FLOAT_VECTOR'&&row.index_type==='HNSW'" class="index-param"><span>efConstruction（构建搜索范围）</span><el-input-number v-model="row.index_params.efConstruction" :min="1" :max="65536" size="small" /></div></template></el-table-column><el-table-column label="操作" width="75"><template #default="{ $index }"><el-button type="danger" link @click="removeField($index)">删除</el-button></template></el-table-column></el-table><p class="schema-note">至少需要一个主键和一个 FLOAT_VECTOR 字段，向量维度须与 Embedding 模型输出一致。为兼容 LlamaIndex 及知识库权限过滤，请保留默认字段：id（VARCHAR 主键，不自动生成，由节点 ID 写入）、vector（FLOAT_VECTOR）、text（VARCHAR）、user_id（VARCHAR）、document_id（VARCHAR）、filename（VARCHAR）。用户权限、文档删除和来源展示依赖后三个字段。</p><template #footer><el-button @click="showAddDialog=false">取消</el-button><el-button type="primary" @click="createCollection">创建集合</el-button></template></el-dialog><el-dialog v-model="showSchemaDialog" :title="`集合 Schema：${schemaCollection.name}`" width="900px"><el-table :data="schemaCollection.fields" border height="55vh" style="width:100%"><el-table-column prop="name" label="字段名" min-width="140" show-overflow-tooltip/><el-table-column prop="dtype" label="数据类型" min-width="140"/><el-table-column prop="description" label="字段描述" min-width="180" show-overflow-tooltip/><el-table-column label="参数" min-width="180" show-overflow-tooltip><template #default="{row}">{{ Object.entries(row.params||{}).map(([key,value]) => `${key}: ${value}`).join(', ') || '-' }}</template></el-table-column><el-table-column label="索引" min-width="160"><template #default="{row}"><el-tag v-for="idx in (schemaCollection.index||[]).filter(item=>item.field===row.name)" :key="idx.field" size="small">{{ idx.index_type }}{{ idx.metric_type ? ` / ${idx.metric_type}` : '' }}</el-tag><span v-if="!(schemaCollection.index||[]).some(item=>item.field===row.name)">无</span></template></el-table-column><el-table-column label="主键" width="90"><template #default="{row}">{{ row.is_primary ? '是' : '否' }}</template></el-table-column><el-table-column label="自动生成" width="100"><template #default="{row}">{{ row.auto_id ? '是' : '否' }}</template></el-table-column></el-table><template #footer><el-button @click="showSchemaDialog=false">关闭</el-button></template></el-dialog><el-dialog v-model="showEditDescriptionDialog" title="编辑集合描述" width="520px"><el-form label-width="90px"><el-form-item label="集合名称"><el-input :model-value="editingCollection.name" disabled /></el-form-item><el-form-item label="描述"><el-input v-model="editingCollection.description" type="textarea" :rows="4" maxlength="256" show-word-limit /></el-form-item></el-form><template #footer><el-button @click="showEditDescriptionDialog=false">取消</el-button><el-button type="primary" @click="saveCollectionDescription">保存</el-button></template></el-dialog></div>
</template>
<script setup>
import { ref, reactive, onMounted } from 'vue'
import axios from 'axios'
import { ElMessage, ElMessageBox } from 'element-plus'
const headers = () => ({})
const activeTab=ref('llm'), saving=ref(false), loadingRemote=ref(false), showAddDialog=ref(false), showEditDescriptionDialog=ref(false), showSchemaDialog=ref(false), remoteCollections=ref([]), editingCollection=reactive({name:'',description:''}), schemaCollection=reactive({name:'',fields:[]})
const llmConfig=reactive({base_url:'',api_key:'',model:'',temperature:0.7}), embeddingConfig=reactive({base_url:'',api_key:'',model:'',dimension:2048,max_tokens:8192}), milvusConfig=reactive({uri:'',user:'',password:'',database:'',collections:[]}), agentConfig=reactive({max_iterations:8}), mcpServers=ref([])
const fieldTypes=['BOOL','INT8','INT16','INT32','INT64','FLOAT','DOUBLE','VARCHAR','JSON','FLOAT_VECTOR','BINARY_VECTOR']
const collectionForm=reactive({name:'',description:'',fields:defaultKnowledgeFields()})
function isVector(type){return type==='FLOAT_VECTOR'||type==='BINARY_VECTOR'}
function defaultKnowledgeFields(){return [{name:'id',data_type:'VARCHAR',description:'Primary key (LlamaIndex node ID)',is_primary:true,auto_id:false,max_length:65535},{name:'vector',data_type:'FLOAT_VECTOR',description:'Embedding vector',is_primary:false,auto_id:false,dimension:embeddingConfig.dimension||2048,index_type:'AUTOINDEX',metric_type:'COSINE',index_params:{}},{name:'text',data_type:'VARCHAR',description:'Document text',is_primary:false,auto_id:false,max_length:65535},{name:'user_id',data_type:'VARCHAR',description:'User ID for retrieval permission filtering',is_primary:false,auto_id:false,max_length:256},{name:'document_id',data_type:'VARCHAR',description:'Document ID for deletion and filtering',is_primary:false,auto_id:false,max_length:256},{name:'filename',data_type:'VARCHAR',description:'Source filename for retrieval display',is_primary:false,auto_id:false,max_length:1024}]}
function addField(){collectionForm.fields.push({name:`field_${collectionForm.fields.length+1}`,data_type:'VARCHAR',description:'',is_primary:false,auto_id:false,max_length:256,index_type:'AUTOINDEX',metric_type:'COSINE',index_params:{}})}
function removeField(index){collectionForm.fields.splice(index,1)}
function primaryChanged(selected){if(selected)collectionForm.fields.forEach(field=>{if(field!==selected)field.is_primary=false})}
function typeChanged(field){if(field.data_type==='VARCHAR'&&!field.max_length)field.max_length=256;if(isVector(field.data_type)&&!field.dimension)field.dimension=embeddingConfig.dimension||2048}
function resetCollectionForm(){Object.assign(collectionForm,{name:'',description:'',fields:defaultKnowledgeFields()})}
onMounted(async()=>{try{const {data}=await axios.get('/api/config/',{headers:headers()});Object.assign(llmConfig,data.llm||{});Object.assign(embeddingConfig,data.embedding||{});Object.assign(milvusConfig,data.milvus||{});Object.assign(agentConfig,data.agent||{});milvusConfig.collections||=[];mcpServers.value=(data.mcp_servers||[]).map(server=>({...server,_existing:true}))}catch{ElMessage.error('加载配置失败，请检查管理员 Token')}})
function addMcpServer(){mcpServers.value.push({id:`remote-${Date.now()}`,name:'',transport:'streamable-http',url:'',token:'',enabled:true})}
async function saveConfigs(){saving.value=true;try{const servers=mcpServers.value.map(({_existing,...server})=>server);const {data}=await axios.put('/api/config/',{...llmConfig,...embeddingConfig,...milvusConfig,...agentConfig,mcp_servers:servers},{headers:headers()});ElMessage.success(data.message||'配置已保存')}catch(e){ElMessage.error('保存失败：'+(e.response?.data?.detail||e.message))}finally{saving.value=false}}
async function testMcpServer(server){try{const {data}=await axios.post('/api/config/mcp/test',{...server,token:server.token||''},{headers:headers()});data.status==='ok'?ElMessage.success(`${data.message}：${data.tools.map(tool=>tool.name).join(', ')}`):ElMessage.error(data.message)}catch(e){ElMessage.error(e.response?.data?.detail||e.message)}}
async function testConnection(service){try{const {data}=await axios.post(`/api/config/test/${service}`,null,{headers:headers()});data.status==='ok'?ElMessage.success(data.message):ElMessage.error(data.message);if(service==='milvus'&&data.status==='ok')loadRemoteCollections()}catch(e){ElMessage.error(e.response?.data?.detail||e.message)}}
function viewCollectionSchema(row){schemaCollection.name=row.name;schemaCollection.fields=row.fields||[];schemaCollection.index=row.index||[];showSchemaDialog.value=true}
async function loadRemoteCollections(){loadingRemote.value=true;try{const {data}=await axios.get('/api/config/milvus/collections',{headers:headers()});if(data.status==='ok')remoteCollections.value=data.collections;else ElMessage.error(data.message)}catch(e){ElMessage.error(e.response?.data?.detail||e.message)}finally{loadingRemote.value=false}}
async function createCollection(){try{const primary=collectionForm.fields.find(field=>field.is_primary);const fieldNames=new Set(collectionForm.fields.map(field=>field.name));if(!collectionForm.name.trim())throw new Error('请填写集合名称');if(!primary)throw new Error('请选择一个主键字段');if(primary.name!=='id'||primary.data_type!=='VARCHAR')throw new Error('知识库集合主键必须命名为 id，类型为 VARCHAR');if(primary.auto_id)throw new Error('知识库集合的 id 主键不能自动生成，需使用 LlamaIndex 节点 ID');if(!fieldNames.has('vector')||!collectionForm.fields.some(field=>field.name==='vector'&&field.data_type==='FLOAT_VECTOR'))throw new Error('必须包含名为 vector 的 FLOAT_VECTOR 字段');if(!fieldNames.has('text')||!collectionForm.fields.some(field=>field.name==='text'&&field.data_type==='VARCHAR'))throw new Error('必须包含名为 text 的 VARCHAR 字段');if(!fieldNames.has('user_id')||!collectionForm.fields.some(field=>field.name==='user_id'&&field.data_type==='VARCHAR'))throw new Error('必须包含名为 user_id 的 VARCHAR 字段用于权限过滤');if(!fieldNames.has('document_id')||!collectionForm.fields.some(field=>field.name==='document_id'&&field.data_type==='VARCHAR'))throw new Error('必须包含名为 document_id 的 VARCHAR 字段用于按文档删除');if(!fieldNames.has('filename')||!collectionForm.fields.some(field=>field.name==='filename'&&field.data_type==='VARCHAR'))throw new Error('必须包含名为 filename 的 VARCHAR 字段用于来源展示');if(primary.auto_id&&primary.data_type!=='INT64')throw new Error('自动生成主键仅支持 INT64');const {data}=await axios.post('/api/config/milvus/create-collection',collectionForm,{headers:headers()});if(data.status==='ok'){ElMessage.success(data.message);showAddDialog.value=false;resetCollectionForm();loadRemoteCollections()}else ElMessage.error(data.message)}catch(e){ElMessage.error(e.response?.data?.detail||e.message)}}
function editCollection(row){editingCollection.name=row.name;editingCollection.description=row.description||'';showEditDescriptionDialog.value=true}
async function saveCollectionDescription(){try{const {data}=await axios.put(`/api/config/milvus/collections/${encodeURIComponent(editingCollection.name)}`,{description:editingCollection.description},{headers:headers()});if(data.status==='ok'){ElMessage.success(data.message);showEditDescriptionDialog.value=false;loadRemoteCollections()}else ElMessage.error(data.message)}catch(e){ElMessage.error(e.response?.data?.detail||e.message)}}
async function deleteCollection(name){try{await ElMessageBox.confirm(`确认删除集合“${name}”？此操作不可恢复。`,'确认',{type:'warning'})}catch{return}try{const {data}=await axios.delete(`/api/config/milvus/collections/${encodeURIComponent(name)}`,{headers:headers()});if(data.status==='ok'){ElMessage.success(data.message);loadRemoteCollections()}else ElMessage.error(data.message)}catch(e){ElMessage.error(e.response?.data?.detail||e.message)}}
</script>
<style scoped>
.index-param{display:flex;flex-direction:column;gap:2px;margin-top:5px;font-size:11px;color:#606266;white-space:normal}.config-view,.config-card{height:100%}.card-header,.section-header,.field-header{display:flex;justify-content:space-between;align-items:center}.section-header{margin:20px 0 16px}.field-header{margin:14px 0}.collection-actions{display:flex;justify-content:center;align-items:center;gap:8px}.collection-actions :deep(.el-button){margin-left:0}.schema-note{color:#667085;font-size:13px;margin-top:12px}.el-tag{margin:2px}</style>
